#!/usr/bin/env bash
# Prints deploy/alerts/prometheusrule.yaml: the Prometheus Operator
# PrometheusRule holding the groups of deploy/alerts/agentfs.rules.yml,
# the one file the rules are edited in. The alerts workflow fails when the
# committed file differs from this output; after editing the rules run
#
#   ci/alerts-prometheusrule.sh >deploy/alerts/prometheusrule.yaml

set -euo pipefail

rules=$(dirname "$0")/../deploy/alerts/agentfs.rules.yml
cat <<'EOF'
# GENERATED by ci/alerts-prometheusrule.sh from deploy/alerts/agentfs.rules.yml:
# edit that file, then regenerate this one. Explained in docs/deployment.md
# ("Alerts"). Your Prometheus Operator's ruleSelector may need a label
# added here (kube-prometheus-stack's default selects `release: <its release>`).
apiVersion: monitoring.coreos.com/v1
kind: PrometheusRule
metadata:
  name: agentfs
  labels:
    app.kubernetes.io/name: agentfs
spec:
EOF
# The rules file without its header comment, indented under spec.
sed -n '/^groups:/,$p' "$rules" | sed 's/^/  /'
